package com.tripsync.controller;import com.tripsync.dto.InvitationDtos.*;import com.tripsync.service.InvitationService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/groups/{groupId}/invitations")public class InvitationController{private final InvitationService service;public InvitationController(InvitationService s){service=s;}@PostMapping public InvitationResponse create(@PathVariable UUID groupId,@Valid @RequestBody CreateInvitation r,@RequestHeader(value="X-User-Id",defaultValue="demo-user")String user){return service.create(groupId,user,r.invitee());}@PostMapping("/accept")public Map<String,String> accept(@PathVariable UUID groupId,@Valid @RequestBody AcceptInvitation r,@RequestHeader(value="X-User-Id",defaultValue="demo-user")String user){service.accept(r.token(),user);return Map.of("status","accepted");}}
